'use strict';
// אוצר החכמה, בר אילן והתקליטור התורני בקלוד: תוסף לאפליקציית קלוד למחשב (MCP דרך stdio, בלי ספריות חיצוניות).
// הכול רץ במחשב של המשתמש: התוסף מפעיל את הגשר (ktiv-bridge.ps1 -Local) כתהליך-בן, שולח לו משימות בשורות JSON,
// והגשר מחפש באוצר החכמה, בבר אילן ובתקליטור התורני על שולחן עבודה נסתר. שום דבר לא עובר דרך שרת.
// הקובץ הזה וכל מה שבתיקייה app מתעדכנים לבד: server/index.js (המטען הקבוע) טוען את הגרסה החתומה החדשה ביותר.

const { spawn } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const readline = require('readline');
const syntax = require('./syntax');
const verify = require('./verify');

const VERSION = process.env.KB_APP_VERSION || 'dev';   // גרסת התוסף (מהמטען: זו שבחבילה או זו שהורדה)
const WAIT_MS = +(process.env.KB_WAIT_MS || 50000);   // כמה לחכות בתוך קריאה אחת לכלי; אחר כך מחזירים job_id
const MAX_IMAGES = 2;
const PS1 = process.env.KB_PS1 || path.join(__dirname, 'ktiv-bridge.ps1');
const BRIDGE = { version: (() => { try { return (/\$VERSION\s*=\s*'([^']+)'/.exec(fs.readFileSync(PS1, 'utf8')) || [])[1] || ''; } catch (e) { return ''; } })(),
  from: process.env.KB_APP_FROM || 'bundle' };
const IMG_DIR = path.join(os.tmpdir(), 'otzar-barilan-claude');
const CONF = {
  // ההגדרות בתוסף (manifest user_config): צילום או טקסט מאוצר החכמה, מכמה ספרים, כמה תוצאות מבר אילן ומהתקליטור
  result: /^(1|true|yes)$/i.test(process.env.OTZAR_IMAGE || '') ? 'image' : ['text', 'image', 'ref'].includes(process.env.OTZAR_RESULT) ? process.env.OTZAR_RESULT : 'text',
  // כמה תוצאות מוצגות עם הטקסט המלא. MAX_HITS (תוסף 1.5–1.6, ברירת מחדל 4) לא נקרא: הצגה רחבה יותר היא ברירת המחדל מ-1.7
  maxHits: Math.max(1, Math.min(30, parseInt(process.env.MAX_TEXTS || '10', 10) || 10)),
  listMax: Math.max(4, Math.min(300, parseInt(process.env.LIST_MAX || '150', 10) || 150)),     // כמה מקומות מביאים ורושמים בכל חיפוש
  pages: Math.max(0, Math.min(5, parseInt(process.env.OTZAR_PAGES || '2', 10) || 0)),
  allowClose: /^(1|true|yes)$/i.test(process.env.ALLOW_CLOSE_OTZAR || ''),
};

function log(...a) { process.stderr.write('[otzar-barilan] ' + a.join(' ') + '\n'); }

// ---------------------------------------------------------------- הגשר (תהליך PowerShell)

let child = null, ready = null, seq = 0, stderrTail = '';
const START_MS = +(process.env.KB_START_MS || 75000);   // קלוד מוותר על קריאה לכלי אחרי 2 דקות: כל המתנה כאן קצרה מזה
const jobs = new Map();       // id -> {state, result, error, progress, waiters: []}
const queue = [];             // משימות שמחכות לגשר (הוא מבצע אחת בכל פעם)
let busy = null;

function startBridge() {
  if (child) return ready;
  fs.mkdirSync(IMG_DIR, { recursive: true });
  const cmd = process.env.KB_SPAWN ? JSON.parse(process.env.KB_SPAWN) : ['powershell.exe', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', PS1, '-Local', '-ImgDir', IMG_DIR];
  child = spawn(cmd[0], cmd.slice(1), { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
  child.stdin.setDefaultEncoding('utf8');
  ready = new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error('The search bridge (PowerShell) did not start within ' + Math.round(START_MS / 1000) + ' seconds.' + why()));
      try { child && child.kill(); } catch (e) {}   // הקריאה הבאה תנסה מחדש
    }, START_MS);
    child._ready = () => { clearTimeout(timer); resolve(); };
    child._fail = e => { clearTimeout(timer); reject(e); };
  });
  ready.catch(() => {});
  readline.createInterface({ input: child.stdout }).on('line', onLine);
  child.stderr.on('data', d => { stderrTail = (stderrTail + String(d)).slice(-1500); log('bridge stderr:', String(d).slice(0, 500)); });
  child.on('error', e => { log('bridge error', e.message); if (child && child._fail) child._fail(e); });
  child.on('exit', code => {
    log('bridge exited', code);
    if (child && child._fail) child._fail(new Error('The search bridge (PowerShell) stopped while starting (exit ' + code + ').' + why()));
    const err = 'The search bridge stopped (exit ' + code + ').';
    if (busy) finish(busy, null, err);
    child = null; ready = null; busy = null;
    if (queue.length) pump();
  });
  return ready;
}

function why() {
  const t = stderrTail.replace(/\s+/g, ' ').trim();
  return (t ? ' PowerShell said: ' + t.slice(-600) : '') +
    ' The log is in %LOCALAPPDATA%\\OtzarBarilanClaude\\bridge.log. Possible causes: antivirus blocking PowerShell scripts, or PowerShell disabled by policy.';
}

function onLine(line) {
  const i = line.indexOf('@@KB@@');
  if (i < 0) return;
  let m;
  try { m = JSON.parse(line.slice(i + 6)); } catch (e) { log('bad line', line.slice(0, 200)); return; }
  if (m.ready) { child && child._ready && child._ready(); return; }
  if (m.progress !== undefined) { if (busy && jobs.has(busy)) jobs.get(busy).progress = m.progress; return; }
  if (m.id) { finish(m.id, m.result, m.error); busy = null; pump(); }
}

function finish(id, result, error) {
  const j = jobs.get(id);
  if (!j || j.state !== 'running' && j.state !== 'queued') return;
  j.state = error ? 'error' : 'done'; j.result = result; j.error = error || null;
  for (const w of j.waiters.splice(0)) w();
}

async function pump() {
  if (busy || !queue.length) return;
  const id = queue.shift(), j = jobs.get(id);
  busy = id; j.state = 'running';
  try {
    await startBridge();
    child.stdin.write(JSON.stringify({ id, kind: j.kind, params: j.params }) + '\n');
  } catch (e) {
    finish(id, null, e.message); busy = null; pump();
  }
}

function submit(kind, params) {
  const id = 'j' + (++seq) + '_' + Date.now().toString(36);
  jobs.set(id, { kind, params, state: 'queued', result: null, error: null, progress: '', waiters: [], created: Date.now() });
  queue.push(id); pump();
  for (const [k, v] of jobs) if (Date.now() - v.created > 6 * 3600e3) jobs.delete(k);   // ניקוי
  return id;
}

function waitJob(id, ms) {
  const j = jobs.get(id);
  if (!j || j.state === 'done' || j.state === 'error') return Promise.resolve(j);
  return new Promise(resolve => {
    const t = setTimeout(() => resolve(jobs.get(id)), ms);
    j.waiters.push(() => { clearTimeout(t); resolve(jobs.get(id)); });
  });
}

