async function run(p, label) {
  const id = submit('batch', p);
  searching++;
  let j;
  try { j = await waitJob(id, WAIT_MS); if (j.state === 'done' || j.state === 'error') return format(j); }
  finally { searching--; }
  return [{ type: 'text', text: `The search is still running on this computer (${label}). Call get_results with job_id="${id}" to wait for it.` + (j.progress ? ' Progress: ' + j.progress : '') }];
}

async function call(name, a) {
  a = a || {};
  if (name === 'bridge_status') {
    const id = submit('selftest', {});
    const j = await waitJob(id, 100000);
    if (!j || j.state !== 'done') throw new ToolError('The search bridge did not answer: ' + ((j && j.error) || 'timeout'));
    const c = j.result.caps || {}, o = c.otzar || {}, r = c.responsa || {}, d = c.dbs || {};
    return [{ type: 'text', text: [
      'Otzar HaChochma: ' + (o.installed ? 'installed' : 'not found') + (o.editor_open ? ', open on the user\'s screen (it is skipped unless the user allows closing it)' : '') + (o.installed && !o.disk ? ', its disk may not be connected' : '') + '.',
      'Bar-Ilan Responsa: ' + (r.installed ? 'installed' + (r.version ? ' (' + r.version + ')' : '') : 'not found') + '.',
      'HaTaklitor HaTorani: ' + (d.installed ? 'installed' : 'not found') + (d.editor_open ? ', open on the user\'s screen' : '') + '.',
      'Closing Otzar for a moment when it is open: ' + (CONF.allowClose ? 'allowed in the settings' : 'not allowed in the settings') + '.',
      'Extension ' + VERSION + (BRIDGE.from === 'update' ? ' (updated automatically)' : '') + ', search bridge ' + (j.result.version || BRIDGE.version) + '.'].join('\n') }];
  }
  if (name === 'otzar_pages') {
    const q = String(a.query || '').trim(), books = (a.books || []).map(n => parseInt(n, 10)).filter(n => n >= 0).slice(0, 8);
    if (!q || !books.length) throw new ToolError('query and books are required');
    const id = submit('otzar_books', { query: q, books, otzar_result: ['text', 'image'].includes(a.result) ? a.result : (CONF.result === 'image' ? 'image' : 'text') });
    searching++;
    let j;
    try { j = await waitJob(id, 100000); } finally { searching--; }
    if (!j || j.state !== 'done') throw new ToolError('Otzar did not answer: ' + ((j && j.error) || 'timeout'));
    const r = j.result || {};
    if (r.state !== 'ok') return [{ type: 'text', text: 'Otzar HaChochma: ' + (r.message || r.state) }];
    const images = [], lines = [`## Otzar HaChochma: ${q} – pages from books ${books.map(b => '#' + b).join(', ')}`];
    for (const p of r.pages || []) {
      if (p.error) { lines.push(`### #${p.idx}: could not open the book (${p.error})`); continue; }
      const text = (p.text || '').trim(), pg = p.page_label || (p.page > 0 ? p.page : '');
      const rid = verify.add({ prog: 'otzar', title: `${p.title || ''}${p.author ? ' / ' + p.author : ''}`, ref: pg ? 'page ' + pg : '', text, ocr: true, refOnly: !text });
      if (p.image) images.push(p.image);
      lines.push(`### [${rid}] #${p.idx} ${p.title || ''}${p.author ? ' / ' + p.author : ''}${pg ? ', page ' + pg : ''}\n` + (text ? '[Otzar OCR - may contain errors]\n' + text : p.image ? '[page image attached]' : '[no text]'));
    }
    const content = [{ type: 'text', text: lines.join('\n\n') }];
    for (const f of images.slice(0, MAX_IMAGES)) { try { content.push({ type: 'image', data: fs.readFileSync(f).toString('base64'), mimeType: 'image/png' }); } catch (e) {} }
    return content;
  }
  if (name === 'read_results') {
    for (let t = 0; searching > 0 && t < 600; t++) await new Promise(r => setTimeout(r, 100));
    const out = [];
    for (const raw of (a.ids || []).slice(0, 40)) {
      const s = verify.SOURCES.get(String(raw).trim().toUpperCase());
      out.push(s ? `[${s.id}] ${[s.title, s.ref].filter(Boolean).join(', ')}\n${s.text || '[reference only]'}` : `[${raw}] unknown id`);
    }
    return [{ type: 'text', text: out.join('\n\n') || 'No ids.' }];
  }
  if (name === 'verify_quotes') {
    for (let t = 0; searching > 0 && t < 600; t++) await new Promise(r => setTimeout(r, 100));
    return [{ type: 'text', text: verify.check(a.quotes) }];
  }
  if (name === 'get_results') {
    const id = String(a.job_id || '');
    if (!jobs.has(id)) throw new ToolError('Unknown job_id (results are kept for 6 hours, and are lost when Claude restarts).');
    const j = await waitJob(id, WAIT_MS);
    if (j.state === 'done' || j.state === 'error') return format(j);
    return [{ type: 'text', text: `Still running${j.progress ? ' (' + j.progress + ')' : ''}. Call get_results again with job_id="${id}".` }];
  }
  if (name === 'search_otzar' || name === 'search_responsa' || name === 'search_dbs') {
    const prog = { search_otzar: 'otzar', search_responsa: 'responsa', search_dbs: 'dbs' }[name];
    const q = String(a.query || '').trim();
    if (!q) throw new ToolError('query is empty');
    const fb = (a.fallbacks || []).map(f => String(f).trim()).filter(Boolean).slice(0, 4);
    return run(params([{ key: q, [prog]: [q, ...fb] }], { otzar: prog === 'otzar', responsa: prog === 'responsa', dbs: prog === 'dbs' }, a), name);
  }
  if (name === 'search_concepts') {
    const con = (a.concepts || []).map(c => Array.isArray(c) ? c : [c]);
    const anchor = (a.anchor || []).map(String).filter(x => x.trim());
    const items = [syntax.item(con, anchor.length ? anchor : null), anchor.length ? syntax.item(con) : null].filter(Boolean);
    if (!items.length) throw new ToolError('concepts are empty');
    const progs = new Set(a.programs && a.programs.length ? a.programs : ['otzar', 'responsa', 'dbs']);
    const ctl = a.control && a.control.length ? syntax.item(a.control.filter(w => String(w).trim()).map(w => [w])) : null;
    return run(params(items, { otzar: progs.has('otzar'), responsa: progs.has('responsa'), dbs: progs.has('dbs') }, a, ctl), name);
  }
  throw new ToolError('Unknown tool: ' + name);
}

// ---------------------------------------------------------------- עיצוב התוצאה

function format(j) {
  if (j.state === 'error') throw new ToolError('The search failed on this computer: ' + (j.error || 'unknown error'));
  const res = j.result || {}, out = [], images = [];
  for (const [key, one] of Object.entries(res.results || {}))
    for (const [prog, r] of Object.entries(one || {})) out.push(fmtProg(prog, key, r || {}, images, (j.params && j.params.max_hits) || CONF.maxHits));
  for (const [prog, v] of Object.entries(res.control || {})) {
    const nm = NAMES[prog] || prog;
    if (v.state === 'ok' && !v.count) out.push(`CONTROL CHECK in ${nm}: even the control words were not found - the search there is not working as expected.`);
    else if (v.state === 'ok') out.push(`Control check in ${nm}: OK (${v.count} hits${v.vi ? ', the strict form failed, so looser forms were used' : ''}).`);
  }
  if (res.note) out.push('Note: ' + res.note);
  const content = [{ type: 'text', text: out.filter(Boolean).join('\n\n') || 'No results.' }];
  for (const f of images.slice(0, MAX_IMAGES)) {
    try { content.push({ type: 'image', data: fs.readFileSync(f).toString('base64'), mimeType: 'image/png' }); } catch (e) { log('image', e.message); }
  }
  return content;
}

const NAMES = { otzar: 'Otzar HaChochma', responsa: 'Bar-Ilan Responsa', dbs: 'HaTaklitor HaTorani' };

function fmtProg(prog, key, r, images, showN) {
  const name = NAMES[prog] || prog;
  const used = r.used || key;
  if (r.state && r.state !== 'ok') return `## ${name}: ${used}\n` + (r.state === 'busy' ? 'Skipped: ' + (prog === 'otzar' ? 'Otzar is open on the user\'s screen.' : (r.message || 'the program is busy.')) : (r.message || r.state));
  const lines = [`## ${name}: ${used}`];
  if (used !== key) lines.push(`(the stricter form "${key}" found nothing; this looser form was used)`);
  if (prog === 'responsa' || prog === 'dbs') {
    // כל המקומות נשמרים בתוסף עם מזהה; הראשונים מוצגים עם הטקסט המלא, והשאר ברשימה (read_results מביא את הטקסט שלהם)
    const hits = r.hits || [], show = Math.max(1, +(showN || CONF.maxHits));
    const total = r.count != null ? r.count : hits.length;
    lines.push(`${total} results${hits.length ? `; ${hits.length} places fetched${hits.length < total ? ' (the list is capped)' : ''}` : ' - nothing found'}.`);
    const rest = [];
    hits.forEach((h, i) => {
      const id = verify.add({ prog, title: (h.title || '').trim(), ref: '', text: (h.text || '').trim(), ocr: false });
      if (i < show) lines.push(`[${id}] ${(h.title || '').trim()}\n${(h.text || '').trim()}`);
      else rest.push(`[${id}] ${(h.title || '').trim()}`);
    });
    if (rest.length) lines.push(`More places (${rest.length}; get their text with read_results):\n` + rest.join('\n'));
    return lines.join('\n');
  }
  lines.push(`${r.count != null ? r.count : '?'} hits in ${r.books_total || (r.books || []).length} books.`);
  const books = r.books || [];
  if (books.length) lines.push(`Books (${books.length}${r.books_total > books.length ? ' of ' + r.books_total : ''}, by number of hits):\n` + books.map((b, i) => `- #${b.idx != null ? b.idx : i} ${b.title || ''}${b.author ? ' / ' + b.author : ''} (${b.n || '?'})`).join('\n'));
  for (const p of r.pages || []) {
    const text = (p.text || '').trim(), pg = p.page_label || (p.page > 0 ? p.page : '');
    const id = verify.add({ prog, title: `${p.title || ''}${p.author ? ' / ' + p.author : ''}`, ref: pg ? 'page ' + pg : '', text, ocr: true, refOnly: !text });
    const head = `### [${id}] ${p.title || ''}${p.author ? ' / ' + p.author : ''}${pg ? ', page ' + pg : ''}`;
    if (p.image) images.push(p.image);
    lines.push(head + '\n' + (text ? '[Otzar OCR - may contain errors]\n' + text : p.image ? '[page image attached]' : '[reference only - the wording was not copied]'));
  }
  return lines.join('\n');
}

