const VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05'];

function send(m) { process.stdout.write(JSON.stringify(m) + '\n'); }

async function handle(m) {
  const { id, method } = m, p = m.params || {};
  if (id === undefined || id === null) {                // הודעה: אין תשובה
    // מחממים את הגשר מראש (PowerShell והידור), כדי שהחיפוש הראשון לא יחכה לעלייה
    if (method === 'notifications/initialized' && !process.env.KB_NO_PREWARM) setTimeout(() => { if (!child) startBridge().catch(e => log('prewarm', e.message)); }, 1500);
    return;
  }
  const ok = result => send({ jsonrpc: '2.0', id, result });
  if (method === 'initialize') {
    if (global.__kbReady) global.__kbReady();   // המטען: הגרסה הזו עלתה ועונה (אחרת הוא חוזר לגרסה שבחבילה)
    return ok({ protocolVersion: VERSIONS.includes(p.protocolVersion) ? p.protocolVersion : VERSIONS[0], capabilities: { tools: { listChanged: false } },
      serverInfo: { name: 'otzar-barilan', title: 'אוצר החכמה, בר אילן והתקליטור התורני', version: VERSION }, instructions: FULL_INSTRUCTIONS });
  }
  if (method === 'ping') return ok({});
  if (method === 'tools/list') return ok({ tools: TOOLS });
  if (method === 'resources/list') return ok({ resources: [] });
  if (method === 'prompts/list') return ok({ prompts: [] });
  if (method === 'tools/call') {
    try { return ok({ content: await call(p.name, p.arguments), isError: false }); }
    catch (e) { return ok({ content: [{ type: 'text', text: e instanceof ToolError ? e.message : 'Error: ' + e.message }], isError: true }); }
  }
  send({ jsonrpc: '2.0', id, error: { code: -32601, message: 'Method not found: ' + method } });
}

const pending = new Set();

// תמיד רץ כשרת. לא בודקים require.main: אפליקציית קלוד מריצה את התוסף דרך Node משלה, ושם require.main יכול להיות
// אחר – ואז השרת לא היה מאזין לקלט, וקלוד הודיע "Request timed out" (התקנה ראשונה, 09.11.2026).
if (!process.env.KB_NO_MAIN) {
  readline.createInterface({ input: process.stdin }).on('line', line => {
    if (!line.trim()) return;
    let m;
    try { m = JSON.parse(line); } catch (e) { return send({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'Parse error' } }); }
    for (const x of Array.isArray(m) ? m : [m]) {
      const t = handle(x).catch(e => log('handle', e.stack)).finally(() => pending.delete(t));
      pending.add(t);
    }
  });
  // הקלט נסגר (קלוד נסגר): מסיימים את מה שבעבודה (עד שתי דקות), ואז הגשר סוגר את העותקים הנסתרים ויוצא
  process.stdin.on('end', async () => {
    await Promise.race([Promise.allSettled([...pending]), new Promise(r => setTimeout(r, 120000))]);
    if (child) child.stdin.end();
    setTimeout(() => process.exit(0), 3000);
  });
  log('started', VERSION, 'from', BRIDGE.from, 'bridge', BRIDGE.version);
}

module.exports = { handle, call, format, TOOLS, BRIDGE };

