'use strict';
// תרגום חיפוש מובנה (מושגים עם חלופות, ועוגן) לשפת החיפוש של אוצר החכמה, בר אילן והתקליטור התורני.
// זה תרגום מדויק של ktiv/bridge/syntax.py, והבדיקה ktiv/tests/test_bridge_desktop.py משווה בין השניים.
// התחביר נבדק אצל עורך (בדיקות 14–18, נובמבר 2026). פרטים בהערות של syntax.py.

const BAD = /[()/+*\[\]{}:#@^~\\|<>!$%]/g;

function clean(a) {
  const s = String(a == null ? '' : a).replace(BAD, ' ').replace(/״/g, '"').replace(/׳/g, "'");
  return s.split(/\s+/).filter(Boolean).join(' ');
}

function hy(a) { return clean(a).split(' ').filter(Boolean).join('-'); }

function alts(g) {
  const out = [], seen = new Set();
  for (const a of (Array.isArray(g) ? g : [g])) {
    const w = hy(a);
    if (w && !seen.has(w)) { seen.add(w); out.push(w); }
  }
  return out;
}

function group(ws, plus) {
  const single = ws.filter(w => !w.includes('-'));            // ביטוי צמוד לא עובד בתוך סוגריים
  if (ws.length > 1) ws = single.length ? single : ws.slice(0, 1);
  if (ws.length === 1) return (plus && !ws[0].includes('-') ? '+' : '') + ws[0];
  return (plus ? '+' : '') + '(' + ws.join('/') + ')';
}

function otzarVariants(groups, names, neg) {
  const gs = (groups || []).map(alts).filter(w => w.length);
  if (!gs.length) return [];
  const ns = alts(names || []).slice(0, 3);
  const tailNeg = (neg || []).map(hy).filter(Boolean).map(x => '--' + x);
  const build = plus => {
    const base = gs.map(g => group(g, plus)).concat(tailNeg).join(' ');
    return ns.length ? ns.map(n => base + ' ' + n).join(' ++ ') : base;   // העוגן: חיפוש לכל צורה של השם
  };
  const v1 = build(true), v2 = build(false);
  const v3 = gs.map(g => g[0]).concat(ns.length ? [ns[0]] : []).join(' ');
  const out = [];
  for (const v of [v1, v2, v3]) if (!out.includes(v)) out.push(v);
  return out;
}

const RESPONSA_DIST = 8;

function rgroup(ws, mark) {
  const single = ws.filter(w => !w.includes('-'));
  if (ws.length > 1) ws = single.length ? single : ws.slice(0, 1);
  if (ws.length === 1) {
    const w = ws[0];
    if (w.includes('-')) return w.replace(/-/g, ' ');
    return (w.includes('"') ? '+' : mark) + w;
  }
  return '(' + ws.map(w => mark + w).join('/') + ')';
}

function responsaVariants(groups, names) {
  const gs = (groups || []).map(alts).filter(w => w.length);
  if (!gs.length) return [];
  const ns = alts(names || []).filter(n => !n.includes('-')).slice(0, 4);
  const d = RESPONSA_DIST + ': ';
  const tail = ns.length ? [ns.length > 1 ? '(' + ns.join('/') + ')' : ns[0]] : [];
  const v1 = d + gs.map(g => rgroup(g, '#')).concat(tail).join(' ');
  const v2 = d + gs.map(g => rgroup(g, '#')).join(' ');
  return v1 === v2 ? [v1] : [v1, v2];
}

const DBS_DIST = 10, DBS_BOXES = 8, DBS_ALTS = 4;

function dbox(ws, mark) {
  ws = ws.slice(0, DBS_ALTS).map(w => (mark && !w.includes('"') ? mark : '') + w);
  return ws.length === 1 ? ws[0] : '(' + ws.join('/') + ')';
}

function dboxes(gs, mark) {
  let out = [];
  for (const g of gs) {
    const single = g.filter(w => !w.includes('-'));
    if (single.length) out.push(dbox(single, mark));
    else out = out.concat(g[0].split('-').filter(Boolean).map(w => dbox([w], mark)));
  }
  return out.slice(0, DBS_BOXES);
}

function dbsVariants(groups, names) {
  const gs = (groups || []).map(alts).filter(w => w.length);
  if (!gs.length) return [];
  const ns = alts(names || []).filter(n => !n.includes('-'));
  const d = DBS_DIST + ': ';
  const v2 = dboxes(gs, '');
  const v1 = ns.length && v2.length < DBS_BOXES ? v2.concat([dbox(ns, '')]).slice(0, DBS_BOXES) : v2;
  const v3 = dboxes(gs.map(g => g.slice(0, 1)), '');
  const out = [];
  for (const v of [v1, v2, v3]) { const s = d + v.join(' '); if (!out.includes(s)) out.push(s); }
  return out;
}

function item(groups, names, neg) {
  const oz = otzarVariants(groups, names, neg);
  if (!oz.length) return null;
  return { key: oz[0], otzar: oz, responsa: responsaVariants(groups, names), dbs: dbsVariants(groups, names) };
}

module.exports = { otzarVariants, responsaVariants, dbsVariants, item };

files.verify.js:
'use strict';
// בדיקת ציטוטים מול התוצאות שהגיעו מהחיפושים בשיחה: אותה בדיקה של כתיב מלא (ktiv/sources/verify.py, notes.verify_and_clean).
// כל תוצאה עם נוסח מקבלת מזהה (R1, R2...). ציטוט נבדק מול המקור שאליו יוחס; אם הוא לא תואם, בודקים אם הוא נמצא
// דווקא בתוצאה אחרת (מראה מקום שגוי). סף ההתאמה 85%, ומעל 97% זו התאמה מלאה – כמו בכתיב מלא.

const THRESHOLD = 0.85, FULL = 0.97;
const SOURCES = new Map();   // id -> {id, prog, title, ref, text, ocr, refOnly}
let seq = 0;

function add(src) {
  // אותה תוצאה בחיפוש חוזר מקבלת את אותו מזהה
  for (const s of SOURCES.values()) if (s.title === src.title && s.ref === src.ref && s.text === src.text) return s.id;
  const id = 'R' + (++seq);
  SOURCES.set(id, Object.assign({ id }, src));
  if (SOURCES.size > 2000) SOURCES.delete(SOURCES.keys().next().value);
  return id;
}

const FINALS = { 'ך': 'כ', 'ם': 'מ', 'ן': 'נ', 'ף': 'פ', 'ץ': 'צ' };
const OCR = { 'ת': 'ח', 'ס': 'מ', 'ע': 'פ', 'ם': 'מ', 'ך': 'כ' };   // ktiv/hebrew.py OCR_FOLD

function tokens(s, ocr) {
  s = String(s || '').normalize('NFC').replace(/[֑-ׇ]/g, '').replace(/<[^>]+>/g, ' ')
    .replace(/[״“”„]/g, '"').replace(/[׳’‘`]/g, "'").replace(/־/g, ' ').replace(/\*/g, '');
  const out = [];
  for (let w of s.split(/\s+/)) {
    w = w.replace(/[^א-ת0-9a-zA-Z]+/g, '');
    if (!w) continue;
    if (ocr) w = w.replace(/[תסעםך]/g, c => OCR[c]);
    out.push(w.replace(/[ךםןףץ]/g, c => FINALS[c] || c));
  }
  return out;
}

function lcs(a, b) {   // כמה ממילות הציטוט נמצאו בסדרן
  let prev = new Array(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array(b.length + 1).fill(0);
    for (let j = 1; j <= b.length; j++) cur[j] = a[i - 1] === b[j - 1] ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
    prev = cur;
  }
  return prev[b.length];
}

// היחס הטוב ביותר של הציטוט לחלון כלשהו בטקסט, והקטע עצמו
function best(quote, text, ocr) {
  const q = tokens(quote, ocr), s = tokens(text, ocr), raw = String(text || '').replace(/\*/g, '').split(/\s+/).filter(Boolean);
  if (!q.length || !s.length) return { r: 0, at: '' };
  const n = q.length, extra = Math.max(2, Math.floor(n / 5)), qs = new Set(q);
  let top = { r: 0, i: 0 };
  const tried = new Set();
  const starts = [];
  s.forEach((w, i) => { if (qs.has(w)) for (let st = Math.max(0, i - n); st <= i; st++) starts.push(st); });
  for (const st of (starts.length ? starts : [0])) {
    if (tried.has(st)) continue;
    tried.add(st);
    const r = lcs(q, s.slice(st, st + n + extra)) / n;
    if (r > top.r) top = { r, i: st };
    if (top.r > FULL) break;
  }
  return { r: top.r, at: raw.slice(top.i, top.i + n + 2).join(' ') };
}

function name(s) { return s ? `${s.id} (${[s.title, s.ref].filter(Boolean).join(', ')})` : ''; }

function check(items) {
  const out = [];
  for (const it of items || []) {
    const quote = String(it.quote || '').trim(), sid = String(it.source || '').trim().toUpperCase();
    const head = '"' + quote.split(/\s+/).slice(0, 8).join(' ') + (quote.split(/\s+/).length > 8 ? '…' : '') + '"';
    if (quote.split(/\s+/).length < 3) { out.push(`${head}: too short to check (at least 3 words).`); continue; }
    const src = sid ? SOURCES.get(sid) : null;
    if (sid && !src) { out.push(`${head}: unknown source ${sid} (ids are the [R..] marks in the search results of this conversation).`); continue; }
    if (src && src.refOnly) { out.push(`${head}: ✗ ${name(src)} is a reference only – its wording was not copied, so it cannot be quoted. Quote only from a result with text, or cite the book and page without a quotation.`); continue; }
    let res = src ? best(quote, src.text, src.ocr) : { r: 0 };
    if (src && res.r >= THRESHOLD) {
      out.push(`${head}: ✓ ${res.r >= FULL ? 'full' : 'partial'} match ${Math.round(res.r * 100)}% in ${name(src)}` +
        (src.ocr ? ' – Otzar OCR text: check the wording against the page image before quoting.' : '.') +
        (res.r < FULL ? ` The source reads: "${res.at}"` : ''));
      continue;
    }
    // לא תואם למקור שיוחס (או בלי ייחוס): בכל התוצאות של השיחה
    let alt = null, altRes = { r: 0 };
    for (const s of SOURCES.values()) {
      if (s.refOnly || s === src) continue;
      const x = best(quote, s.text, s.ocr);
      if (x.r > altRes.r) { altRes = x; alt = s; }
    }
    if (src && alt && altRes.r >= THRESHOLD)
      out.push(`${head}: ✗ does not match ${name(src)} (${Math.round(res.r * 100)}%), but is found in ${name(alt)} (${Math.round(altRes.r * 100)}%) – fix the reference.`);
    else if (!src && alt && altRes.r >= THRESHOLD)
      out.push(`${head}: ✓ ${Math.round(altRes.r * 100)}% in ${name(alt)}` + (alt.ocr ? ' – Otzar OCR text: check against the page image.' : '.'));
    else
      out.push(`${head}: ✗ NOT FOUND in the search results (best ${Math.round(Math.max(res.r, altRes.r) * 100)}%${src ? ' in ' + name(src) : alt ? ' in ' + name(alt) : ''}). ` +
        'Do not present it as a quotation: mark it as needing a check, or search again for the exact wording.' + (src && res.at ? ` The source reads: "${res.at}"` : ''));
  }
  return out.join('\n') || 'No quotes to check.';
}

module.exports = { add, check, best, tokens, SOURCES, THRESHOLD };
